<script>
	let _this;
	import wInput from '../../components/watch-login/watch-input.vue' //input
	import wButton from '../../components/watch-login/watch-button.vue' //button
	import {
		login
	} from '@/api/login.js';
	import $store from '@/store/modules/social/test.js';

	export default {
		data() {
			return {
				logoImage: 'data:image/image/png;base64,',
				phoneData: '', //用户/电话
				passData: '', //密码
				isRotate: false, //是否加载旋转
				isFocus: true, // 是否聚焦
				codeUrl: "",
				captchaEnabled: true,
				globalConfig: getApp().globalData.config,
				loginForm: {
					userName: undefined,
					password: undefined
				}
			}
		},
		created() {
			const baseUrl = getApp().globalData.baseUrl
			console.log(baseUrl, 'baseUrl') // 这个打印出来就说明没问题，后面都是用这个获取方式就行了
			// this.getCode()
		},
		components: {
			wInput,
			wButton,
		},
		mounted() {
			_this = this;
			//this.isLogin();
		},
		methods: {
			login() {
				let _this = this;
				if (this.loginForm.userName === '' || this.loginForm.password === '') {
					alert('账号或密码不能为空');
				} else {
					login(_this.loginForm).then(res => {
						console.log(res)
						let response_data = res;
						// 将用户token保存到vuex中
						if (response_data.code == 1) {
							_this.userToken = response_data.token;
							uni.setStorageSync("Authorization", _this.userToken)
							
							var resUser = { userId :"1", avartarUrl:"http://first-bucket20201002.oss-cn-hangzhou.aliyuncs.com/img/img/avatar/me.jpg" }
							$store.state.loginUserInfo = resUser;
							uni.setStorageSync('LOGIN_USER_INFO', resUser);
							
							uni.switchTab({
								url: '/pages/index/index'
							});
						} else {
							// alert('账号或密码错误');
						}
					}).catch(error => {
						// alert('账号或密码错误');
						console.log(error);
					});
				}
			}
		}
	}
</script>

